html:
{% if letter_head %}
<div class="letter-head">{{ letter_head }}</div>
{% endif %}
<style>
.sa-wrap { font-family: "Segoe UI", system-ui, sans-serif; color: #1a1a1a; max-width: 800px; margin: 0 auto; padding: 24px; }
.sa-head { border-bottom: 3px solid #0f172a; padding-bottom: 16px; margin-bottom: 24px; }
.sa-title { font-size: 22px; font-weight: 700; letter-spacing: 0.02em; color: #0f172a; margin: 0 0 4px 0; }
.sa-sub { font-size: 12px; color: #64748b; text-transform: uppercase; letter-spacing: 0.08em; }
.sa-badge { display: inline-block; padding: 4px 10px; border-radius: 999px; font-size: 11px; font-weight: 600; background: #ecfdf5; color: #047857; border: 1px solid #a7f3d0; }
.sa-grid { display: table; width: 100%; margin-bottom: 20px; }
.sa-row { display: table-row; }
.sa-cell { display: table-cell; padding: 8px 12px 8px 0; vertical-align: top; font-size: 13px; }
.sa-label { color: #64748b; width: 38%; font-weight: 500; }
.sa-val { font-weight: 600; color: #0f172a; }
.sa-section { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.1em; color: #0f172a; margin: 28px 0 12px 0; padding-bottom: 6px; border-bottom: 1px solid #e2e8f0; }
.sa-table { width: 100%; border-collapse: collapse; font-size: 12px; margin-top: 8px; }
.sa-table th { text-align: left; padding: 8px 10px; background: #f8fafc; border: 1px solid #e2e8f0; }
.sa-table td { padding: 8px 10px; border: 1px solid #e2e8f0; vertical-align: top; }
.sa-notes { font-size: 12px; line-height: 1.6; color: #334155; margin-top: 8px; }
.sa-foot { margin-top: 48px; padding-top: 16px; border-top: 1px solid #e2e8f0; font-size: 11px; color: #94a3b8; text-align: center; }
</style>
<div class="sa-wrap">
  <div class="sa-head">
    <div class="sa-title">{{ _("Support Agreement") }}</div>
    <div class="sa-sub">{{ doc.name }} &nbsp;·&nbsp; {{ doc.customer_name or doc.customer }}</div>
    <p style="margin-top:12px"><span class="sa-badge">{{ doc.status }}</span></p>
  </div>
  <div class="sa-section">{{ _("Parties & validity") }}</div>
  <div class="sa-grid">
    <div class="sa-row"><div class="sa-cell sa-label">{{ _("Customer") }}</div><div class="sa-cell sa-val">{{ doc.customer_name or doc.customer }}</div></div>
    <div class="sa-row"><div class="sa-cell sa-label">{{ _("Customer ID") }}</div><div class="sa-cell sa-val">{{ doc.customer }}</div></div>
    <div class="sa-row"><div class="sa-cell sa-label">{{ _("Division") }}</div><div class="sa-cell sa-val">{{ doc.division }}</div></div>
    <div class="sa-row"><div class="sa-cell sa-label">{{ _("Agreement type") }}</div><div class="sa-cell sa-val">{{ doc.agreement_type }}</div></div>
    <div class="sa-row"><div class="sa-cell sa-label">{{ _("Valid from") }}</div><div class="sa-cell sa-val">{{ doc.get_formatted("valid_from") if doc.valid_from else "—" }}</div></div>
    <div class="sa-row"><div class="sa-cell sa-label">{{ _("Valid to") }}</div><div class="sa-cell sa-val">{{ doc.get_formatted("valid_to") if doc.valid_to else "—" }}</div></div>
    <div class="sa-row"><div class="sa-cell sa-label">{{ _("Project") }}</div><div class="sa-cell sa-val">{{ doc.project or "—" }}</div></div>
  </div>
  <div class="sa-section">{{ _("SLA") }}</div>
  <div class="sa-grid">
    <div class="sa-row"><div class="sa-cell sa-label">{{ _("Response SLA (hours)") }}</div><div class="sa-cell sa-val">{{ doc.response_sla_hours }}</div></div>
    <div class="sa-row"><div class="sa-cell sa-label">{{ _("Resolution SLA (hours)") }}</div><div class="sa-cell sa-val">{{ doc.resolution_sla_hours }}</div></div>
  </div>
  {% if doc.coverage_detail %}
  <div class="sa-section">{{ _("Coverage detail") }}</div>
  <table class="sa-table">
    <thead><tr><th>{{ _("Service category") }}</th><th>{{ _("Covered") }}</th><th>{{ _("Response SLA") }}</th><th>{{ _("Resolution SLA") }}</th></tr></thead>
    <tbody>
    {% for row in doc.coverage_detail %}
      <tr>
        <td>{{ row.service_category }}</td>
        <td>{{ _("Yes") if row.is_covered else _("No") }}</td>
        <td>{{ row.response_sla_hours or "—" }}</td>
        <td>{{ row.resolution_sla_hours or "—" }}</td>
      </tr>
    {% endfor %}
    </tbody>
  </table>
  {% endif %}
  {% if doc.notes %}
  <div class="sa-section">{{ _("Notes") }}</div>
  <div class="sa-notes">{{ doc.notes }}</div>
  {% endif %}
  <div class="sa-foot">{{ _("Generated from ERP — Printechs Support") }}</div>
</div>
